import{_ as r,o as d,c as a,a2 as o}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"双宇食品 · 薯条脆","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/index.md","filePath":"lab/shuangyu-fries/index.md","lastUpdated":1786871523000}'),e={name:"lab/shuangyu-fries/index.md"};function s(n,t,h,g,i,l){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="双宇食品-·-薯条脆" tabindex="-1">双宇食品 · 薯条脆 <a class="header-anchor" href="#双宇食品-·-薯条脆" aria-label="Permalink to &quot;双宇食品 · 薯条脆&quot;">​</a></h1><blockquote><p>46g 杯装 · 番茄味 · VF 工艺 ｜ 交付两支广告片</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>当前阶段</strong></td><td><strong>4 · A 片第一遍效果不理想，已完成 v3 广告化重做执行稿</strong></td></tr><tr><td><strong>卡在哪</strong></td><td>需先按真实设备结构锁定主设备关键帧；本产品前处理、温度参数与脱油工序仍待书面确认</td></tr><tr><td><strong>下一步</strong></td><td>按 <a href="./04h-a-process-v3-researched">A 片 v3 广告化执行稿</a> 先锁 K00 成品钩子与 K02 设备母版 → 分段生成 → 剪成 20s 广告主片</td></tr><tr><td><strong>手上物料</strong></td><td>包装印刷打样文件 + 产品渲染图 + 开盖视频 + VF 通用技术说明</td></tr><tr><td><strong>已知渠道</strong></td><td>抖音短视频 + 电商详情页，<strong>A/B 分工成立</strong>，仅优先级待定</td></tr><tr><td><strong>上市状态</strong></td><td><strong>未上市 · 新品待发</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">本项目的全部记录已公开发布（2026-08-06）</p><p>作战区当日先转为不公开，<strong>同日又决定完全公开</strong>——本页及本项目所有文档现已进入公开仓库与线上站点。</p><p><strong>决定公开时，以下条件全部成立且未解除</strong>：产品未上市、无 NDA、包装渲染图商用授权未确认，且我方物料清单自己写着「未上市则按机密处理」。这是<strong>知情决策，不是遗漏</strong>——与 2026-08-05 那次漏执行性质不同，经过见 <code>specs/2026-08-05-lab-module-design.md</code> 的决策变更记录。</p><p><strong>由此产生一个必办事项</strong>：下一轮沟通须主动向客户说明本项目记录已公开，并补签保密与授权条款。<strong>先说比被发现好。</strong></p><p><strong>写作约束同步升级</strong>：此后写进本项目任何文档的内容，提交即公开、推送即上线，<strong>没有任何技术手段可以拦截或回退</strong>。</p></div><h2 id="文件目录" tabindex="-1">文件目录 <a class="header-anchor" href="#文件目录" aria-label="Permalink to &quot;文件目录&quot;">​</a></h2><h3 id="项目资料" tabindex="-1">项目资料 <a class="header-anchor" href="#项目资料" aria-label="Permalink to &quot;项目资料&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>状态</th></tr></thead><tbody><tr><td><a href="./00-brief">00 · Brief 与解读</a></td><td>✅ 已更新至 2026-08-06（含 VF 资料逐条裁定）</td></tr><tr><td><a href="./01-proposal">01 · 提案</a></td><td>✅ <strong>v1.0 不变</strong>——不因本轮资料改动，理由见决议 ④</td></tr><tr><td><a href="./01a-audience-competitors">01a · 目标人群与竞品</a></td><td>🆕 2026-08-06 · <strong>内部推演，不对客</strong></td></tr><tr><td><a href="./02-materials">02 · 物料清单</a></td><td>✅ <strong>v2 可直接发</strong>（新增 2a–2d 与受限表述说明）</td></tr><tr><td><a href="./05-genlog">05 · 生成日志</a></td><td>🟡 边跑边记</td></tr></tbody></table><h3 id="a-片-·-广告主片" tabindex="-1">A 片 · 广告主片 <a class="header-anchor" href="#a-片-·-广告主片" aria-label="Permalink to &quot;A 片 · 广告主片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>状态</th></tr></thead><tbody><tr><td><a href="./03a-a-process-complete-storyboard">03a · 工艺完整性分镜</a></td><td>v2 · 20 秒 / 11 镜头 / 五个工艺节点</td></tr><tr><td><a href="./04f-a-process-v2-gemini">04f · Gemini 执行表</a></td><td>v2 · 六段生成 + 20 秒后期时间线</td></tr><tr><td><a href="./04h-a-process-v3-researched">04h · 广告化执行稿（工艺考据版）</a></td><td><strong>当前版</strong> · 食欲与产品为主线，VF 工艺作为证据</td></tr></tbody></table><h3 id="b-片-·-开盖片" tabindex="-1">B 片 · 开盖片 <a class="header-anchor" href="#b-片-·-开盖片" aria-label="Permalink to &quot;B 片 · 开盖片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>状态</th></tr></thead><tbody><tr><td><a href="./04c-b-jimeng-v1">04c · 即梦执行表</a></td><td>9:16 开盖片 v1</td></tr><tr><td><a href="./04d-b-gemini-v1">04d · Gemini 执行表</a></td><td>9:16 开盖片 v1</td></tr></tbody></table><h3 id="c-片-·-感官奇观片" tabindex="-1">C 片 · 感官奇观片 <a class="header-anchor" href="#c-片-·-感官奇观片" aria-label="Permalink to &quot;C 片 · 感官奇观片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>状态</th></tr></thead><tbody><tr><td><a href="./03c-c-sensory-wonder-storyboard">03c · 导演分镜</a></td><td>20 秒 / 6 镜头 / 9:16 竖屏</td></tr></tbody></table><h3 id="d-片-·-咔嚓快乐片" tabindex="-1">D 片 · 咔嚓快乐片 <a class="header-anchor" href="#d-片-·-咔嚓快乐片" aria-label="Permalink to &quot;D 片 · 咔嚓快乐片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>状态</th></tr></thead><tbody><tr><td><a href="./03d-d-crunch-happiness-storyboard">03d · 导演分镜</a></td><td>20 秒 / 6 镜头 / 16:9 横屏</td></tr></tbody></table><h3 id="蜂蜜黄油味独立感官创意片" tabindex="-1">蜂蜜黄油味独立感官创意片 <a class="header-anchor" href="#蜂蜜黄油味独立感官创意片" aria-label="Permalink to &quot;蜂蜜黄油味独立感官创意片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>状态</th></tr></thead><tbody><tr><td><a href="./honey-butter/">项目总览</a></td><td><strong>当前推荐方向</strong> · 12 秒 / 9:16 / A-B-C 声音选择题</td></tr><tr><td><a href="./honey-butter/01-creative">01 · 创意</a></td><td>命题、互动机制与创意边界</td></tr><tr><td><a href="./honey-butter/02-keyframes">02 · 关键帧</a></td><td>P0 产品母版 / 10 张关键帧 / 首尾状态</td></tr><tr><td><a href="./honey-butter/03-demo-preview">03 · Demo 预览</a></td><td>四段最小动态 / 12 秒方向预览 / 反馈记录</td></tr><tr><td><a href="./honey-butter/04-storyboard">04 · 分镜</a></td><td>逐镜图生视频、后期任务与正式时间线</td></tr><tr><td><a href="./honey-butter/05-sound-edit">05 · 声音与剪辑</a></td><td>AI 音效、remix、字幕与剪辑节拍</td></tr><tr><td><a href="./honey-butter/06-release-review">06 · 发布与验收</a></td><td>A/B 测试、合规与总验收</td></tr></tbody></table><h3 id="番茄味独立感官创意片" tabindex="-1">番茄味独立感官创意片 <a class="header-anchor" href="#番茄味独立感官创意片" aria-label="Permalink to &quot;番茄味独立感官创意片&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>状态</th></tr></thead><tbody><tr><td><a href="./03f-tomato-sensory-film">03f · 原始导演执行稿</a></td><td>v1 · 20 秒 / 6 镜头 / 16:9 番茄口味 ASMR 执行稿</td></tr><tr><td><a href="./04j-tomato-v2-optimization">04j · v2 成片优化</a></td><td>第一轮视频复盘 · 15 秒 / 6 镜头 / 16:9 完整重做 Prompt</td></tr></tbody></table><h3 id="历史版本与跨片预览" tabindex="-1">历史版本与跨片预览 <a class="header-anchor" href="#历史版本与跨片预览" aria-label="Permalink to &quot;历史版本与跨片预览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>状态</th></tr></thead><tbody><tr><td><a href="./03-storyboard">03 · A 片 demo 分镜</a></td><td>已被 03a 取代</td></tr><tr><td><a href="./04-prompts">04 · A 片 demo Prompt</a></td><td>对应 demo v1</td></tr><tr><td><a href="./04a-jimeng-v1">04a · A 片即梦执行表</a></td><td>v1</td></tr><tr><td><a href="./04b-gemini-v1">04b · A 片 Gemini 执行表</a></td><td>v1</td></tr><tr><td><a href="./04e-gemini-preview-v1">04e · A/B 片 20 秒预览</a></td><td>方向预览，不作成片底料</td></tr><tr><td><a href="./03e-honey-butter-sensory-film">03e · 蜂蜜黄油原始导演执行稿</a></td><td>历史方向 · 20 秒传统 ASMR 执行稿</td></tr><tr><td><a href="./04g-honey-butter-keyframes">04g · 蜂蜜黄油第一轮关键帧</a></td><td>已被 04i 取代</td></tr><tr><td><a href="./04i-honey-butter-v2-optimization">04i · 蜂蜜黄油无包装镜头 v2.1</a></td><td>旧方向技术优化；产品形态资产可复用</td></tr><tr><td>06 · 复盘</td><td>交付后补写</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">分镜是在创意核心未确认的情况下写的</p><p>原则仍然是「提案方向一变，分镜全废」。这次绕过它，理由只有一条：</p><p><strong>镜头 1–9 在任何创意方向下都要用到。</strong> 鲜切、低温油炸、多孔断面、脱油、成品质感——无论主标题最后落在「原薯鲜切」还是「VF 工艺」，这批素材一帧都不浪费，变的只是叙事顺序和字幕。</p><p><strong>真正会废掉的只有落版镜头和整体节奏。</strong> 这是可承受的损失，也是这份分镜敢写的全部依据。</p></div><div class="tip custom-block"><p class="custom-block-title">2026-08-10 · A 片 demo 已完成方向验证</p><p>客户没有否定「原薯鲜切」，但明确要求 A 片重点体现<strong>真空、低温、油炸、脱水、脱脂</strong>，并关注制作细节、节奏与完整性。</p><p>因此 v1 素材不全部推翻：鲜切、安静油面、断面、咔嚓和成品质感继续复用；新增长镜头建立真空，重做脱水与离心脱油，并把五个工艺词拆成独立字幕节拍。执行见 <a href="./03a-a-process-complete-storyboard">03a</a>。</p></div><h2 id="内部决议记录" tabindex="-1">内部决议记录 <a class="header-anchor" href="#内部决议记录" aria-label="Permalink to &quot;内部决议记录&quot;">​</a></h2><blockquote><p>2026-08-05 · 三条关键判断已拍板</p></blockquote><h3 id="_1-创意核心-→-鲜切主、vf-支撑" tabindex="-1">① 创意核心 → 鲜切主、VF 支撑 <a class="header-anchor" href="#_1-创意核心-→-鲜切主、vf-支撑" aria-label="Permalink to &quot;① 创意核心 → 鲜切主、VF 支撑&quot;">​</a></h3><p><strong>决议</strong>：主标题给「原薯鲜切」，VF 作为「为什么鲜切之后还这么脆」的支撑证据。</p><p><strong>理由</strong>：包装上对得上 / 消费者不需要科普就能懂 / <strong>鲜切是消费者自己能验证的承诺</strong>。</p><p><strong>被否</strong>：</p><ul><li><em>VF 做主（客户原话）</em> —— 消费者拿到包装找不到 VF，广告和包装说的不是一件事</li><li><em>两支片各讲一个</em> —— 没有共同记忆点，投放合力变弱；且 B 片只有 6–10 秒，装不下一个完整主张</li></ul><h3 id="_2-片型分工-→-a-主片-b-开盖片" tabindex="-1">② 片型分工 → A 主片 + B 开盖片 <a class="header-anchor" href="#_2-片型分工-→-a-主片-b-开盖片" aria-label="Permalink to &quot;② 片型分工 → A 主片 + B 开盖片&quot;">​</a></h3><p><strong>决议</strong>：A 片 15–20s 讲因果链；<strong>B 片改成「开盖即食」动作片</strong> 6–10s。</p><p><strong>理由</strong>：知识库里的方案是<strong>按袋装推演的</strong>。杯装的撕封口动作补上了袋装零食「缺标志性动作」的死穴，同时补偿了这个产品没有热气造成的信息量缺失。</p><h3 id="_3-日文元素-→-定性前一律不碰" tabindex="-1">③ 日文元素 → 定性前一律不碰 <a class="header-anchor" href="#_3-日文元素-→-定性前一律不碰" aria-label="Permalink to &quot;③ 日文元素 → 定性前一律不碰&quot;">​</a></h3><p><strong>决议</strong>：无书面依据则按「无日本背景」处理。片中不出现日式场景、日文字幕、日式配乐。包装出镜时日文客观存在，不受影响。</p><p><strong>理由</strong>：包装印日文行业常见，通常没问题；<strong>广告主动暗示「这是日本的」性质完全不同</strong>，无对应关系即虚假宣传。</p><p><strong>2026-08-06 定性完成</strong>：客户明确——<strong>日文副标是纯装饰，与日本无任何技术、合作或出口关系。</strong></p><p>决议 ③ 不变，但性质变了：从「<strong>待定性，暂时不碰</strong>」变成「<strong>已定性，确定不碰</strong>」。这不再是一个悬着的风险，而是一条确定的约束。</p><div class="danger custom-block"><p class="custom-block-title">定性为「纯装饰」之后，反而多出一条执行约束</p><p>原决议写「包装出镜时日文客观存在，不受影响」——<strong>这句现在需要补充</strong>。</p><p>不受影响指的是「不必回避」，不等于「可以强调」。<strong>建议在包装出镜的镜头角度与景别上，不刻意突出日文副标。</strong></p><p>两个理由，指向同一个动作：</p><table tabindex="0"><thead><tr><th>角度</th><th>为什么</th></tr></thead><tbody><tr><td><strong>合规</strong></td><td>包装印日文与广告特写日文是两回事。给日文一个特写镜头，在无实质关联的前提下，可能被理解为对来源的暗示</td></tr><tr><td><strong>竞争</strong></td><td>见 <a href="./01a-audience-competitors">01a</a>——杯装 + 条状 + 日文，三个特征叠加，消费者第一联想几乎必然是 Jagariko。<strong>而现在确认了它没有任何实质支撑</strong></td></tr></tbody></table><p>第二条现在才真正成立：<strong>装饰性日文只有借力效果，没有背书价值。</strong> 它既不能证明产品好，又在替竞品做心智教育——强调它是纯亏。</p><p>这条已写入 <a href="./02-materials">02 · 物料清单</a>，并将在分镜阶段落到具体镜头上。</p></div><div class="warning custom-block"><p class="custom-block-title">2026-08-06 补充：这条决议的理由变了，而且变强了</p><p><a href="./01a-audience-competitors">01a · 竞品分析</a> 从竞争角度给出了第二个、且更硬的理由：</p><p><strong>杯装 + 条状 + 日文，三个特征叠在一起，消费者的第一联想几乎必然是 Jagariko。</strong> 广告做日式调性，等于替竞品做心智教育。</p><p><strong>由此，决议 ③ 的适用范围扩大</strong>：原本是「定性前不碰」——拿到书面依据就可以碰；现在建议改为<strong>即使客户拿出真实的日本背景，也不做日式调性</strong>。</p><p>理由从<strong>合规</strong>变成了<strong>竞争</strong>。合规风险可以靠一纸证明解除，竞争劣势不能。</p></div><h3 id="_4-vf-工艺资料-→-收下-但不当作宣称依据" tabindex="-1">④ VF 工艺资料 → 收下，但不当作宣称依据 <a class="header-anchor" href="#_4-vf-工艺资料-→-收下-但不当作宣称依据" aria-label="Permalink to &quot;④ VF 工艺资料 → 收下，但不当作宣称依据&quot;">​</a></h3><blockquote><p>2026-08-06 · 客户以文字形式提供 VF 技术说明后</p></blockquote><p><strong>决议</strong>：资料中可用的只有四条——<strong>多孔结构、80~90℃、脱油离心、酥脆不腻</strong>。其余一律不进片，其中「不生成丙烯酰胺」「规避致癌风险」两条即使日后拿到检测报告也不用。</p><p><strong>理由</strong>：这份资料讲的是 <strong>VF 技术在果蔬脆片上的通用应用，不是薯条脆的工艺文件</strong>——「可泡水复水食用」这一条把它的出身暴露得很清楚。原理可信，但<strong>通用资料不能替本产品背书</strong>。</p><p><strong>由此产生的动作</strong>：物料清单新增 2a–2d（出处、本产品参数、脱油工序、检测报告），并新增一整节向客户逐条说明哪些表述能用、哪些要数据、哪些建议不用。</p><p><strong>提案 v1.0 不改动。</strong> 判断依据：这份材料的性质是<strong>对内的产品认知口径</strong>，客户提供它是为了让我方理解产品，不是要求这些表述进入成片。既然客户没有主张使用，提案的「内容边界」一节按原样即可——那五条红线本就覆盖了这里的风险。</p><div class="warning custom-block"><p class="custom-block-title">一条被撤回的推断</p><p>初稿曾判断「客户发材料 = 客户希望片中用这些话」，据此主张扩充提案的内容边界一节。</p><p><strong>这个推断是错的，已撤回。</strong> 它只依据材料内容本身，没有考虑客户发送时的语境——而这一点只有直接沟通的人知道。</p><p>留档的价值在于：<strong>从文本推断意图，在客户沟通里是高频错误。</strong> 同一份材料，「你参考一下」和「按这个写」是两件事，文本上看不出区别。下次遇到客户主动发材料，先确认它是参考件还是要求件，再决定动不动提案。</p></div><div class="tip custom-block"><p class="custom-block-title">顺带印证了决议 ①</p><p>客户给了 VF 一大堆料，最有传播力的四句（不致癌、低脂、高纤维、无添加）<strong>没有一句能在拿到检测数据前使用</strong>。</p><p>剩下能用的四条，回答的都是「为什么脆而不腻」，<strong>没有一条能回答「为什么买它」</strong>——这正是提案里给 VF 安排的支撑位。</p><p>决议 ① 从一个判断变成了事实。</p></div><h3 id="_5-a-片反馈-→-工艺从支撑位升为主体段落" tabindex="-1">⑤ A 片反馈 → 工艺从支撑位升为主体段落 <a class="header-anchor" href="#_5-a-片反馈-→-工艺从支撑位升为主体段落" aria-label="Permalink to &quot;⑤ A 片反馈 → 工艺从支撑位升为主体段落&quot;">​</a></h3><blockquote><p>2026-08-10 · 客户看过 A 片 demo 后</p></blockquote><p><strong>客户要求</strong>：注意制作细节、节奏调整与制作完整性，重点体现<strong>真空、低温、油炸、脱水、脱脂</strong>。</p><p><strong>决议</strong>：保留「原薯鲜切」作为开头与包装落版主张，但将中段改为一条可读的完整工艺链：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真空 → 低温 → 油炸 → 脱水 → 离心脱油 → 多孔 → 脆</span></span></code></pre></div><p>这不是推翻决议 ①，而是把 VF 从一个合并镜头扩展为全片的主体段落。工艺段占 v2 约 61%，每个节点都有独立画面证据和字幕节拍。</p><p><strong>术语处理</strong>：客户原话「脱脂」留档，成片建议写「离心脱油」。前者容易形成脂肪含量暗示，后者只陈述工序；在检测与书面工艺依据补齐前，不使用「低脂」或任何结果性延伸。</p><h3 id="_6-a-片-v3-→-广告为主-工艺作证" tabindex="-1">⑥ A 片 v3 → 广告为主，工艺作证 <a class="header-anchor" href="#_6-a-片-v3-→-广告为主-工艺作证" aria-label="Permalink to &quot;⑥ A 片 v3 → 广告为主，工艺作证&quot;">​</a></h3><blockquote><p>2026-08-15 · v2 成片方向内部复盘</p></blockquote><p><strong>问题</strong>：v2 虽满足了五个工艺节点的完整性，但工艺段约占 61%，前 13 秒持续解释设备与原理，观看感受接近企业工艺说明片，食欲、口味、包装和取食动作出现太晚。</p><p><strong>决议</strong>：不删工艺证据，但改变它的叙事职能。v3 用成品断裂和主「咔嚓」开场，随后才以 6.4 秒压缩呈现 VF；后半段回到断面、番茄风味、真实开杯和包装落版。工艺占比降至 32%，执行见 <a href="./04h-a-process-v3-researched">04h · 广告化执行稿</a>。</p><p>这不是撤销客户要求，而是重新建立信息层级：<strong>广告负责让人想吃，工艺负责让人相信。</strong> 真空、低温油炸、脱水、离心脱油继续有独立视觉证据，但不再各占一页式字幕节拍。</p><h2 id="待客户确认" tabindex="-1">待客户确认 <a class="header-anchor" href="#待客户确认" aria-label="Permalink to &quot;待客户确认&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>事项</th><th>本轮状态</th></tr></thead><tbody><tr><td>1</td><td>「原薯鲜切」做主标题是否认可</td><td>🟡 客户未直接否定；v3 以「原薯鲜切 · 咔嚓酥脆」落版，VF 作为中段证据，仍待确认</td></tr><tr><td>2</td><td>日文元素有没有真实背景</td><td>✅ <strong>已答：纯装饰，与日本无关系</strong>。决议 ③ 结案，并新增包装出镜的执行约束</td></tr><tr><td>3</td><td>两支片子的投放位与优先级</td><td>🟡 <strong>渠道已知</strong>（抖音 + 详情页），<strong>优先级仍待定</strong></td></tr><tr><td>4</td><td>交期与预算</td><td>🟡 <strong>预算已获知</strong>，不构成约束（内容不入文档，理由见下）；<strong>交期升级为「预计上市时间」</strong>，仍待告知</td></tr><tr><td>5</td><td>产品是否已上市、能否提供实物</td><td>🟡 <strong>已答：未上市</strong>。实物只能由客户提供打样件，我方无法自购</td></tr><tr><td>6</td><td><strong>受限表述是否接受我方处理方式</strong></td><td>🆕 本轮新增</td></tr><tr><td>7</td><td><strong>工艺资料中哪些条目适用于薯条脆</strong></td><td>🆕 本轮新增</td></tr><tr><td>8</td><td><strong>包装设计是否已终稿</strong></td><td>🆕 未上市带出。拿到非终稿等于包装镜头全部返工</td></tr><tr><td>9</td><td><strong>配料表 / 营养成分表是否已定稿</strong></td><td>🆕 未上市带出。若随上市才定，第 3 项将长期阻塞</td></tr><tr><td>10</td><td><strong>目标人群与竞品的书面确认</strong></td><td>🟡 <strong>已口头告知，原话待补入</strong>。补入前 <a href="./01a-audience-competitors">01a</a> 第一、三节不得作为决策依据</td></tr><tr><td>11</td><td><strong>建议零售价与分销渠道</strong></td><td>🆕 物料清单第 13、14 项。<strong>决定片子拍什么，不是决定怎么拍</strong></td></tr><tr><td>12</td><td><strong>是否接受成片以「离心脱油」替代「脱脂」</strong></td><td>🆕 2026-08-10 反馈带出。建议接受，避免被理解为营养含量声称</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">预算为什么只写状态、不写内容</p><p>公开状态下，自我审查是唯一的控制点（见 <code>specs</code> 决策变更记录）。而那张审查表里第二条就是**「未公开的价格条款、合同细节」不写**。</p><p>预算属于双方商业关系信息，<strong>记录它的状态足够支撑排期与制作决策，记录它的内容不增加任何工作价值</strong>。</p><p>这是「完全公开」这个决定在日常写作中的第一个具体约束——<strong>它不是一次性的，是此后每一次落笔都要过的一道</strong>。</p></div><div class="danger custom-block"><p class="custom-block-title">2026-08-06 历史记录：客户回了资料，但七个问题一个都没答</p><p>这一轮客户回应的是<strong>他愿意给的</strong>（工艺资料），不是<strong>我们要的</strong>（源文件、配料表、五个决策）。</p><p>这是很常见的一种反应——<strong>给材料比做决定容易</strong>。回复时要把「感谢资料」和「但这七条仍在等」分成两段写清楚，不能混在一起，否则等于默认这一轮的沟通完成了。</p></div><h2 id="关键风险" tabindex="-1">关键风险 <a class="header-anchor" href="#关键风险" aria-label="Permalink to &quot;关键风险&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>等级</th><th>状态</th></tr></thead><tbody><tr><td>客户要求做对比片</td><td>🔴 法律问题</td><td>提案里已主动挡掉并说明定性</td></tr><tr><td>客户要求说「非油炸 / 更健康」</td><td>🔴 VF 就是油炸</td><td>提案「内容边界」一节已列明。2026-08-06 客户资料含此类表述，但<strong>属对内认知口径、客户未主张使用</strong>，暂不升级</td></tr><tr><td>通用技术资料被当作本产品依据</td><td>🟠</td><td>已列为索要项 2a–2d，出处未确认前不引用</td></tr><tr><td><s>广告暗示日本进口</s></td><td>🟢 <strong>已关闭</strong></td><td>已定性为纯装饰。片中不出现日式元素，<strong>且包装出镜时不突出日文副标</strong>——见决议 ③</td></tr><tr><td>只有渲染图，做不了包装镜头</td><td>🟠</td><td>物料清单第 1 项</td></tr><tr><td><strong>渲染图的商用授权未确认</strong></td><td>🟠</td><td>物料清单「保密与授权」</td></tr><tr><td><strong>未上市信息公开发布在本站</strong></td><td>🔴 <strong>知情接受</strong></td><td>2026-08-06 决定作战区完全公开，<strong>而产品仍未上市</strong>。见页首。不可撤销，须向客户说明</td></tr><tr><td><strong>保密条款尚未与客户谈过</strong></td><td>🔴 <strong>由 🟠 升级</strong></td><td>无 NDA、无书面约定，<strong>而记录已公开</strong>——两者叠加后这一条从待办变成了必须立刻处理</td></tr><tr><td>包装设计可能尚未定稿</td><td>🔴</td><td>非终稿 = 包装镜头全部返工。已列为索要项 1a</td></tr><tr><td>配料表随上市才定稿</td><td>🟠</td><td>若成立，营养类表述短期内全都用不了</td></tr></tbody></table><h2 id="和教学案例的关系" tabindex="-1">和教学案例的关系 <a class="header-anchor" href="#和教学案例的关系" aria-label="Permalink to &quot;和教学案例的关系&quot;">​</a></h2><p>知识库里的 <a href="/cases/case-04-vf-fries-crisp">案例 04</a> 是同题材的<strong>纸上推演</strong>。方法论骨架能用，但<strong>五条产品假设错了四条</strong>——对照表在 <a href="./00-brief#教学演示案例被推翻的假设">00 · Brief</a>。</p><p>那张表是这个项目最有价值的副产品，交付后脱敏写进 <code>cases/</code>。</p>',69)])])}const b=r(e,[["render",s]]);export{c as __pageData,b as default};
